	function api(endpoint, method, body, contentType = 'application/json') {
		
		const controller = new AbortController()
		const signal = controller.signal
		setTimeout(() => controller.abort(), 500)

		let data = {
			signal,
			method: method,
			headers: {
				'Content-Type': contentType
			} 
		}

		if (body) {
			data['body'] = JSON.stringify(body)
		}

		return fetch(`${API_URI}/${endpoint}`, data)
		.then(response => {
			if (!response.ok) {
				throw Error(response.statusText)
			}

			return response.json()
		})
		.then(response => {
			return response.data
		})
		.catch(error => {
			console.log('API request failed:', error.message)

			return false
		})
	}

The `abortcontroller-polyfill`  works

A code snippet:

```javascript
import "abortcontroller-polyfill";

class App extends React.Component {
    constructor() {
        const AbortController = window.AbortController;
        this.controller = new AbortController();
        this.signal = this.controller.signal;
    }
    componentDidMount() {
        const url = "https://myurl.com";
        const signal = this.signal;

        fetch(url, { signal })
        .then(res => res.json())
        .then(json => console.log(json))
        .catch(err => {
            // You can catch the error
            // thrown by the polyfill here.
            if (err.name == "AbortError") {
                console.log("Fetch Aborted");
            } else {
               //Catch other errors.
            }
        });
    }
    componentWillUnmount() {
        this.controller.abort();
    }
    /*--Rest of the code.--*/
}
```
